from itertools import permutations
faces=["Hand","Leg","Eyes","Nose","Mouth","Ear"]
views=[("Hand","Leg","Eyes"),("Hand","Nose","Leg"),("Leg","Nose","Mouth")]
adj={f:set() for f in faces}
for v in views:
    for a in v:
        for b in v:
            if a!=b: adj[a].add(b)
# find pairings into 3 opposite pairs consistent with adjacency
res=set()
def pairings(rem):
    if not rem: yield []; return
    a=rem[0]
    for b in rem[1:]:
        r=[x for x in rem if x not in (a,b)]
        for p in pairings(r): yield [(a,b)]+p
for p in pairings(faces):
    if all(b not in adj[a] for a,b in p):
        for a,b in p:
            if a=="Hand": res.add(b)
            if b=="Hand": res.add(a)
assert res=={"Mouth"}
opts={"A":"Ear","B":"Nose","C":"Mouth","D":"Leg"}
r=res.pop()
assert r==opts["C"] and all(r!=opts[k] for k in "ABD")

from itertools import permutations
faces=['Hand', 'Leg', 'Eyes', 'Nose', 'Mouth', 'Ear']
views=[['Hand', 'Leg', 'Eyes'], ['Hand', 'Nose', 'Leg'], ['Leg', 'Nose', 'Mouth']]
adj=set()
for v in views:
    for a in v:
        for b in v:
            if a!=b: adj.add(frozenset((a,b)))
sols=set()
for p in permutations(faces):
    pairs=[frozenset((p[0],p[1])),frozenset((p[2],p[3])),frozenset((p[4],p[5]))]
    if any(q in adj for q in pairs): continue
    for q in pairs:
        if 'Hand' in q: sols.add(next(iter(q-{'Hand'})))
assert len(sols)==1
ans=sols.pop()
opts={'A': 'Ear', 'B': 'Nose', 'C': 'Mouth', 'D': 'Leg'}
assert ans==opts['C']
for k,v in opts.items():
    if k!='C': assert ans!=v

from itertools import combinations
lines=[{'R', 'T', 'P'}, {'R', 'B'}, {'L', 'Q', 'B'}, {'L', 'T'}, {'O', 'T', 'B'}, {'O', 'R', 'L'}, {'O', 'P', 'Q'}]
pts=set().union(*lines)
def on(a,b): return any(a in l and b in l for l in lines)
def col(a,b,c): return any({a,b,c}<=l for l in lines)
n=len([c for c in combinations(sorted(pts),3) if on(c[0],c[1]) and on(c[1],c[2]) and on(c[0],c[2]) and not col(*c)])
opts={'A': 16, 'B': 12, 'C': 10, 'D': 14}
assert n==opts['B']
for k,v in opts.items():
    if k!='B': assert n!=v

